using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using MicroEMR.Web.Models.PatientResults;using MicroEMR.Web.Services.PatientResults;namespace MicroEMR.Web.Controllers;[Authorize]public sealed class PatientResultsController:Controller{private readonly IPatientResultApiClient c;public PatientResultsController(IPatientResultApiClient x)=>c=x;[HttpGet]public async Task<IActionResult>List(Guid patientUid,string status="New",CancellationToken t=default)=>Json(new{success=true,results=await c.List(patientUid,status,t)});[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(SavePatientResultViewModel x,CancellationToken t){if(!ModelState.IsValid)return BadRequest(new{success=false,message="Result name and date are required."});return Json(new{success=true,result=await c.Create(x.PatientUid,x,t)});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Update(UpdatePatientResultViewModel x,CancellationToken t){if(!ModelState.IsValid)return BadRequest(new{success=false,message="Invalid result."});try{return Json(new{success=true,result=await c.Update(x.PatientUid,x.PatientResultUid,x,t)});}catch(HttpRequestException e)when(e.StatusCode==System.Net.HttpStatusCode.Conflict){return Conflict(new{success=false,message=e.Message});}}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Review(ReviewPatientResultViewModel x,CancellationToken t)=>Json(new{success=true,result=await c.Review(x.PatientUid,x.PatientResultUid,x,t)});}
